// Adapters translate native quotes into the shared review grammar. No second repair/swap rules.
const id=v=>JSON.stringify(v),fmt=n=>Number(n).toFixed(2),pct=n=>Math.round(n*100)+'%',short=key=>{const k=JSON.parse(key);return k.id||(k.components?Object.values(k.components).join(' + '):'item');};
const effect=(label,before,after)=>({label,before,after,changed:before!==after});
export function toolRepairPorts(p){
 const read=()=>{const v=p.tools();return {identity:id(v),title:'Tool repair · condition & risk',choiceLabel:'Carried or equipped tool',reviewLabel:'Review repair',current:v.job?`Repair active: ${v.job.name}`:'Hand repair keeps the same tool instance.',options:v.rows.map(r=>({id:r.key,label:`${r.name} · ${fmt(r.condition)}/${fmt(r.max)}`,available:r.condition<r.max,reason:r.diagnosis||'Native requirements and shortages appear in the quote.'})),help:'A timed repair reserves the quoted materials. Staying idle at the same place advances it. Short inputs may still permit a weaker, riskier attempt.'};};
 function preview(key){const q=p.quoteRepair({key}),v=p.tools(),rows=[];
 if(q.condition!=null){rows.push(effect('Condition',fmt(q.condition)+' / '+fmt(q.max),q.repairDamage?'Ordinary wear unchanged; crack closure on success':`${fmt(Math.min(q.max,q.condition+q.restore))} / ${fmt(q.max)} if successful`));rows.push(effect('Best condition',fmt(q.max),`${fmt(Math.max(Math.min(q.max,q.floor),q.max-q.failureLoss))} if failed`));}
 const needs=q.inputs?.map(r=>(r.met?'Met: ':'Short: ')+r.label).join(' · ')||'';
 return {identity:id(v),eligible:q.eligible,native:q,effects:rows,summary:`${q.name||'Tool'}: ${q.chance!=null?pct(q.chance)+' success chance. ':''}${needs}`,cost:`${q.minutes??'?'} played minutes of supported idle work · ${q.spent?.map(r=>r.count+' '+r.id).join(', ')||'no carried repair materials reserved'} · no coin charge for this hand-repair command.`,disposition:`${q.failure||''} Condition changes at settlement, not when work starts. Cancel returns the job's reserved materials under native rules.`,reason:q.reason,action:'Start timed repair'};
 }
 return {read,preview,commit:r=>{p.executeRepair(r.native);return 'Repair started. Materials reserved; condition is unchanged until the native job settles.';}};
}
export function gearSwapPorts(p,{selectedItem,selectedSlot,selectedMaker,onResult}){
 function candidates(v,key,slot){return v.materials.map(m=>({m,q:p.quoteWorkshop({maker:selectedMaker(),action:'swap',key,slot,material:m.key})}));}
 function read(){const v=p.gear(),key=selectedItem(),slot=selectedSlot();return {identity:id([v,key,slot,selectedMaker()]),title:'Gear component swap · custody & effects',choiceLabel:'Carried replacement part',reviewLabel:'Review component swap',current:`${v.rows.find(r=>r.key===key)?.name||'Select carried gear'} · ${slot||'choose slot'} · ${selectedMaker()==='player'?'your work':'old craftsman'}`,options:candidates(v,key,slot).map(({m,q})=>({id:m.key,label:`${m.name} ×${m.count}${q.eligible?' · compatible':' · unavailable'}`,available:q.eligible,reason:q.reason||'Native quote permits this component and maker.'})),help:'Swapping is an immediate native commitment. The removed component returns degraded; gear identity, condition and provenance continue.'};}
 function preview(material){const v=p.gear(),key=selectedItem(),q=p.quoteWorkshop({maker:selectedMaker(),action:'swap',key,slot:selectedSlot(),material}),effects=[];
 if(q.eligible){const a=p.describe(key),b=p.describe(q.receive[0].key);effects.push(effect('Quality',fmt(a.quality)+'%',fmt(b.quality)+'%'));if(a.attack!=null)effects.push(effect('Unworn base item attack',String(a.attack),String(b.attack)));if(a.defense!=null)effects.push(effect('Unworn base item defense',String(a.defense),String(b.defense)));effects.push(effect('Condition',fmt(q.condition),fmt(q.condition)));for(const slot of Object.keys(a.components))effects.push(effect(slot,a.components[slot],b.components[slot]));}
 return {identity:read().identity,eligible:q.eligible,native:q,effects,summary:q.summary||'No supported swap for this choice.',cost:`Immediate operation under current native rules; no elapsed-time or coin charge. Consumes: ${q.spend.slice(1).map(r=>r.count+' '+short(r.key)).join(', ')||'none quoted'}.${q.commission?' Includes the craftsman’s quoted service material.':''}`,disposition:q.eligible?`Original assembly is transformed, not duplicated. Returned parts: ${q.receive.slice(1).map(r=>`${r.count} ${short(r.key)} (${JSON.parse(r.key).quality}% quality)`).join(', ')||'none'}. Unworn base values exclude durability and character combat modifiers; the same current condition is retained.`:'Nothing is committed.',reason:q.reason,action:'Commit component swap'};
 }
 return {read,preview,commit:r=>{const result=p.executeWorkshop(r.native);onResult(result.resultKey);return 'Component swapped through the native workshop. Inspect the retained identity, condition and returned part in inventory.';}};
}
